CREATE TYPE "curso" AS ENUM (
	'ciencia da computacao',
	'engenharia de software',
	'analise de sistemas',
	'sistema da informacao'
);

CREATE TYPE "periodo" AS ENUM (
	'matutino',
	'noturno'
);

CREATE TABLE IF NOT EXISTS "usuario" (
	-- Identificador do usuario
	--
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"nome" VARCHAR(255) NOT NULL,
	"email" VARCHAR(255),
	"senha" VARCHAR NOT NULL,
	"ativo" BOOLEAN NOT NULL,
	"data_nasc" DATE,
	"cpf" INTEGER,
	"aluno_id" INTEGER UNIQUE,
	"coordenador_id" INTEGER UNIQUE,
	"admin_id" INTEGER UNIQUE,
	"cpa_externo_id" INTEGER UNIQUE,
	PRIMARY KEY("id")
);

COMMENT ON COLUMN "usuario"."id" IS 'Identificador do usuario
';

CREATE TABLE IF NOT EXISTS "aluno" (
	"id" INTEGER NOT NULL UNIQUE,
	"curso" CURSO NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "coordenador" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "administrativo" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "cpa_externo" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	PRIMARY KEY("id")
);

ALTER TABLE "usuario"
ADD FOREIGN KEY("cpa_externo_id") REFERENCES "cpa_externo"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "administrativo"
ADD FOREIGN KEY("id") REFERENCES "usuario"("admin_id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "aluno"
ADD FOREIGN KEY("id") REFERENCES "usuario"("aluno_id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "coordenador"
ADD FOREIGN KEY("id") REFERENCES "usuario"("coordenador_id")
ON UPDATE NO ACTION ON DELETE NO ACTION;

-- Usuarios de exemplo (senha: senha123)

-- Aluno: aluno_id e preenchido antes de criar a linha de aluno.
INSERT INTO "usuario" ("nome", "email", "senha", "ativo", "aluno_id")
VALUES ('Aluno Exemplo', 'aluno@exemplo.com', 'senha123', TRUE, 1);
INSERT INTO "aluno" ("id", "curso") VALUES (1, 'ciencia da computacao');

