INSERT INTO "usuario" ("nome", "email", "senha", "ativo", "coordenador_id")
VALUES ('Coordenador Exemplo', 'coordenador@exemplo.com', 'senha123', TRUE, 1);
INSERT INTO "coordenador" ("id") VALUES (1);

-- Administrativo
INSERT INTO "usuario" ("nome", "email", "senha", "ativo", "admin_id")
VALUES ('Administrativo Exemplo', 'administrativo@exemplo.com', 'senha123', TRUE, 1);
