-- CPA Externo: a FK fica em usuario, entao cpa_externo entra primeiro.
INSERT INTO "cpa_externo" ("id") VALUES (1);
INSERT INTO "usuario" ("nome", "email", "senha", "ativo", "cpa_externo_id")
VALUES ('Avaliador Externo', 'externo@exemplo.com', 'senha123', TRUE, 1);
